head.script:

	scwin.onpageload = function() {
		var row = 320;
		var col = 5;
		var data = [];
        var toq = new Array(20);
		for(var i = 0; i < row; i++){
			for(var j = 0; j < col; j++){
                var ss = i * col + j;
                if ( j === 0) {
                    data.push(i + 1);
                } else if (i % 5 === 0) {
                    data.push(toq.join(ss + "\n"));
                } else {
                    data.push(ss);
                }
			}
		}
		dataList1.setData(data);

        var xx = textbox1.id;
        setInterval(function(){
            if (window.N && window.NN) {
                $p.getComponentById(xx).setLabel(window.N + "," + window.NN)
            }

        }, 100)
	};

    scwin.btn_style_onclick = function() {
        gridView1.setCellBackgroundColor(7,3, "red");
        gridView1.setCellBackgroundColor(121,1, "black");
    }

    scwin.btn_merge_onclick = function() {
        gridView1.mergeCell({
            "rowIndex" : 1,
            "colIndex" : 3,
            "rowSpan" : 2,
            "colSpan" : 2
        });
        gridView1.mergeCell({
            "rowIndex" : 95,
            "colIndex" : 1,
            "rowSpan" : 15,
            "colSpan" : 3
        });
    }

	scwin.onpageunload = function() {

	};

    scwin.gridView1_onscrolly = function(e) {
        console.log(this.id + "_onscroll")
    }

    scwin.gridView1_onscrollend = function() {
        console.log(this.id + "_onscrollend")
    }

	scwin.checkVal = function() {
		if(WebSquare.wUnit.getDomById('gridView1_cell_0_0').innerText == '1' 
			&& document.getElementById('mf_gridView1_body_tbody').children[5].style.display != 'none'){
			return true;
		}else{
			return false;
		}

	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_scrollY_div').scrollTop = 30");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
